const _hmac=(key,data)=>{if(typeof key==='string')key=Buffer.from(key,'utf8');if(typeof data==='string')data=Buffer.from(data,'utf8');if(key.length>64)key=_sha256(key);const kp=Buffer.alloc(64);key.copy(kp);const ik=Buffer.alloc(64),ok=Buffer.alloc(64);for(let i=0;i<64;i++){ik[i]=kp[i]^0x36;ok[i]=kp[i]^0x5c;}return _sha256(Buffer.concat([ok,_sha256(Buffer.concat([ik,data]))]));};
const secret = '__REDACTED_JWT_SECRET__'; // hardcoded: set N8N_RUNNERS_ALLOWED_ENV_VARS=JWT_SECRET on server for prod
const ttlHrs = 8760; // 1 year (365 * 24)

const b64url = (buf) =>
  Buffer.from(buf)
    .toString('base64')
    .replace(/=+$/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');

const now     = Math.floor(Date.now() / 1000);
const header  = { alg: 'HS256', typ: 'JWT' };
const payload = {
  sub:   $json.user_id,
  email: $json.email,
  iat:   now,
  exp:   now + ttlHrs * 3600
};

const h   = b64url(JSON.stringify(header));
const p   = b64url(JSON.stringify(payload));
const sig = b64url(_hmac(secret, h + '.' + p));
const token = h + '.' + p + '.' + sig;

return [{ json: { token, user_id: $json.user_id, email: $json.email } }];
